reserved_word:
-- Put the name in double quotes wherever it is used:
SELECT "{word}" FROM ...;
-- or rename it once (SQLite 3.25+):
ALTER TABLE {table} RENAME COLUMN "{word}" TO {word}_value;

check_violation:
-- The rule that failed: {constraint}
-- See the table's rules:
SELECT sql FROM sqlite_master WHERE type = 'table' AND name = '{table}';

fk_missing_parent:
-- This connection checks foreign keys (PRAGMA foreign_keys = ON). SQLite's message doesn't say which side failed:
-- adding/changing a child row -> its parent row must exist first; deleting/changing a parent -> child rows still point to it.
PRAGMA foreign_key_list({table});

fk_has_children:
-- Rows in another table still point to this one; find them:
PRAGMA foreign_key_check;
-- delete or move them first, or declare the link with ON DELETE CASCADE / SET NULL (a table rebuild in SQLite).

disk_full:
-- SQLite needs free space for the file AND its journal. Check the disk, and any page limit:
PRAGMA page_count;
PRAGMA max_page_count;

db_file_locked:
-- A transaction that reads and then writes: take the write lock at the start, and keep it short
BEGIN IMMEDIATE;
-- ... reads and writes ...
COMMIT;

alter_not_supported:
-- SQLite's ALTER TABLE can only RENAME TO, RENAME COLUMN, ADD COLUMN, DROP COLUMN (3.35+). Anything else is a rebuild:
PRAGMA foreign_keys = OFF;
BEGIN;
CREATE TABLE {table}_new (... the new definition ...);
INSERT INTO {table}_new (cols) SELECT cols FROM {table};
DROP TABLE {table};
ALTER TABLE {table}_new RENAME TO {table};
PRAGMA foreign_key_check;
COMMIT;
PRAGMA foreign_keys = ON;
